ValidationRule.errorConditionFormula:
AND(
    NOT($User.BypassValidationRules__c),
    NOT(ISBLANK(ISIN__c)),

    OR(
        /* Contrôle du format général de l'ISIN */
        NOT(
            REGEX(
                ISIN__c,
                "^[A-Z]{2}[A-Z0-9]{9}[0-9]$"
            )
        ),

        /* France */
        AND(
            ISPICKVAL(
                ProjectShareclasses__r.ProjectProduct__r.DomiciledIn__c,
                "FR"
            ),
            NOT(BEGINS(ISIN__c, "FR"))
        ),

        /* Luxembourg */
        AND(
            ISPICKVAL(
                ProjectShareclasses__r.ProjectProduct__r.DomiciledIn__c,
                "LU"
            ),
            NOT(BEGINS(ISIN__c, "LU"))
        ),

        /* Ireland */
        AND(
            ISPICKVAL(
                ProjectShareclasses__r.ProjectProduct__r.DomiciledIn__c,
                "IE"
            ),
            NOT(BEGINS(ISIN__c, "IE"))
        ),

        /* United Kingdom */
        AND(
            ISPICKVAL(
                ProjectShareclasses__r.ProjectProduct__r.DomiciledIn__c,
                "GB"
            ),
            NOT(BEGINS(ISIN__c, "GB"))
        )
    )
)
